var i=`1149-poutine`;var a=`world-1149`;var n=`CA`;var o=`northern-america`;var r=4;var s=42;var l={en:`Poutine`,ua:`Путін (страва)`};var u={en:`Poutine is a dish from Canada prepared with potato, all-purpose flour, mozzarella. This is a home-scale version with measured ingredients in the individual steps where they are used. Mozzarella replaces fresh squeaky cheese curds in this home poutine; melting and texture differ.`,ua:`Путін (страва), страва кухні країни Канада, яку готують із таких продуктів: картопля, пшеничне борошно універсальне, моцарела. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Моцарела замінює свіжі сирні зерна у домашньому путіні; плавлення й текстура відрізняються.`};var d=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`potato`,900,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 18 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 18 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:18,i:[[`canola-oil`,900,`ml`]]},{en:`Melt the fat, stir in flour and cook gently for about 10 minutes, then whisk in liquid to create a smooth thickened sauce.`,ua:`Розтопіть жир, вмішайте борошно й готуйте на малому вогні приблизно 10 хвилин, потім поступово влийте рідину, збиваючи до гладкого густого соусу.`,t:[`roux-making`],m:10,i:[[`unsalted-butter`,50,`g`],[`all-purpose-flour`,50,`g`],[`beef-stock`,650,`ml`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:4,i:[[`mozzarella`,300,`g`],[`ground-black-pepper`,3,`g`]]}];var h={slug:i,id:a,country:`CA`,region:o,servings:4,minutes:42,title:l,text:u,steps:d};export{n as country,h as default,a as id,s as minutes,o as region,r as servings,i as slug,d as steps,u as text,l as title};